<?php
namespace App\Http\Controllers;
use App\Models\{Region,Localite,Ogd,Processus,Provenance,Qualification,Relance,User,DelaiTraitement};
use App\Services\EcheanceService; use Barryvdh\DomPDF\Facade\Pdf; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
abstract class DossierController extends Controller {
 protected string $module,$modelClass,$prefix,$label,$nameField='demandeur';
 protected function model(){return app($this->modelClass);} protected function guardRoles(...$roles){abort_unless(auth()->check()&&auth()->user()->isRole(...$roles),403,'Accès non autorisé.');}
 protected function options(){return ['regions'=>Region::where('actif',1)->orderBy('nom')->get(),'localites'=>Localite::where('actif',1)->orderBy('nom')->get(),'ogds'=>Ogd::where('actif',1)->orderBy('nom')->get(),'processus'=>Processus::where('actif',1)->orderBy('libelle')->get(),'provenances'=>Provenance::where('actif',1)->whereIn('module',[$this->module,'commun'])->orderBy('libelle')->get(),'qualifications'=>Qualification::where('actif',1)->where('module',$this->module)->orderBy('libelle')->get(),'responsables'=>User::where('actif',1)->orderBy('nom')->orderBy('prenom')->get()];}
 protected function filteredDossiers(Request $request){$statuses=$this->module==='reclamation'?'brouillon,recu,a_affecter,affecte,en_cours,en_attente_information,traite,cloture,annule':'brouillon,recu,a_affecter,affecte,en_cours,en_attente_information,traite,a_notifier,cloture,annule';$filters=$request->validate(['recherche'=>'nullable|string|max:150','statut'=>['nullable','in:'.$statuses]]);$table=$this->model()->getTable();$q=$this->model()->select($table.'.*')->addSelect(['droits_statut'=>DB::table('droits_assures')->select('statut')->whereColumn('droits_assures.numero_amo_recepisse',$table.'.numero_amo_recepisse')->limit(1),'droits_date_debut'=>DB::table('droits_assures')->select('date_debut')->whereColumn('droits_assures.numero_amo_recepisse',$table.'.numero_amo_recepisse')->limit(1),'droits_date_fin'=>DB::table('droits_assures')->select('date_fin')->whereColumn('droits_assures.numero_amo_recepisse',$table.'.numero_amo_recepisse')->limit(1),'carte_disponibilite'=>DB::table('disponibilite_cartes')->select('disponibilite')->whereColumn('disponibilite_cartes.numero_amo_recepisse',$table.'.numero_amo_recepisse')->orderByDesc('date_mise_a_jour')->orderByDesc('id')->limit(1),'carte_numero'=>DB::table('disponibilite_cartes')->select('numero_carte')->whereColumn('disponibilite_cartes.numero_amo_recepisse',$table.'.numero_amo_recepisse')->orderByDesc('date_mise_a_jour')->orderByDesc('id')->limit(1)])->with(['region','localite','ogd','qualification','responsable','provenance','processus'])->orderByDesc('date_reception');if(!empty($filters['statut']))$q->where('statut',$filters['statut']);if(!empty($filters['recherche'])){$term=trim($filters['recherche']);$q->where(function($x)use($term){$like='%'.$term.'%';$x->where('numero_ordre','like',$like)->orWhere($this->nameField,'like',$like)->orWhere('objet','like',$like)->orWhere('numero_amo_recepisse','like',$like)->orWhere('numero_matricule','like',$like);});}return $q;}
 public function index(Request $request){$dossiers=$this->filteredDossiers($request)->paginate(15)->withQueryString();return view('dossiers.index',['dossiers'=>$dossiers,'module'=>$this->module,'label'=>$this->label,'prefix'=>$this->prefix]);}
 public function exportPdf(Request $request){$dossiers=$this->filteredDossiers($request)->get();$filters=['recherche'=>$request->input('recherche'),'statut'=>$request->input('statut')];return Pdf::loadView('dossiers.pdf',['dossiers'=>$dossiers,'module'=>$this->module,'label'=>$this->label,'filters'=>$filters,'logoData'=>'data:image/png;base64,'.base64_encode(file_get_contents(public_path('img/LogoCANAM.png'))),'generatedAt'=>now()->format('d/m/Y H:i')])->setPaper('a4','landscape')->download($this->prefix.'-'.now()->format('Y-m-d').'.pdf');}
 public function create(){return view('dossiers.form',array_merge($this->options(),['dossier'=>null,'module'=>$this->module,'label'=>$this->label,'prefix'=>$this->prefix]));}
 protected function rules(){return ['date_reception'=>'required|date','reclamant'=>($this->module==='reclamation'?'required|string|max:180':'nullable'),'demandeur'=>($this->module==='assistance'?'required|string|max:180':'nullable'),'region_id'=>'nullable|exists:regions,id','localite_id'=>'nullable|exists:localites,id','numero_amo_recepisse'=>'nullable|string|max:100','numero_matricule'=>'nullable|string|max:100','contact'=>'nullable|string|max:80','ogd_id'=>'nullable|exists:ogds,id','objet'=>'required|string','provenance_id'=>'nullable|exists:provenances,id','qualification_id'=>['nullable','exists:qualifications,id'],'processus_id'=>'nullable|exists:processus,id','causes_probleme'=>'nullable|string','action_entreprise'=>'nullable|string','date_emission_carte'=>'nullable|date','observations'=>'nullable|string','priorite'=>'required|in:basse,normale,haute,urgente'];}
 public function store(Request $request,EcheanceService $service){$data=$request->validate($this->rules());$data['numero_ordre']=strtoupper(($this->module==='reclamation'?'REC':'ASS').'-'.now()->format('Ymd').'-'.Str::upper(Str::random(5)));$data['cree_par']=auth()->id();$data['statut']='recu';$rule=$service->regle($this->module,$data['qualification_id']??null,\Carbon\Carbon::parse($data['date_reception']));$data['delai_traitement_id']=$rule?->id;$data['date_affectation']=null;$data['echeance_traitement']=$rule && $rule->point_depart==='reception' ? $service->calculer($this->module,$data['qualification_id']??null,$data['date_reception']) : null;$d=$this->model()->create($data);$this->history($d,null,'recu','Enregistrement du dossier');return redirect()->route($this->prefix.'.show',$d->id)->with('success','Dossier enregistré. Échéance : '.($d->echeance_traitement?->format('d/m/Y H:i')??'calculée lors de l’affectation si le délai part de l’affectation'));}
 public function show($id){$d=$this->model()->with(['region','localite','ogd','qualification','responsable','provenance','processus'])->findOrFail($id);$fk=$this->module==='reclamation'?'reclamation_id':'demande_assistance_id';$relances=Relance::where('module',$this->module)->where($fk,$d->id)->latest('date_relance')->get();$historique=DB::table('historique_statuts')->where('module',$this->module)->where($fk,$d->id)->orderByDesc('date_changement')->get();$notifications=$this->module==='assistance'?DB::table('notifications_assistance')->where('demande_assistance_id',$d->id)->orderByDesc('date_appel')->get():collect();return view('dossiers.show',array_merge(['dossier'=>$d,'relances'=>$relances,'historique'=>$historique,'notifications'=>$notifications,'module'=>$this->module,'label'=>$this->label,'prefix'=>$this->prefix],$this->options()));}
 public function edit($id){$d=$this->model()->findOrFail($id);return view('dossiers.form',array_merge($this->options(),['dossier'=>$d,'module'=>$this->module,'label'=>$this->label,'prefix'=>$this->prefix]));}
 public function update(Request $request,$id,EcheanceService $service){$d=$this->model()->findOrFail($id);abort_if(in_array($d->statut,['traite','cloture','annule']),403,'Dossier non modifiable dans ce statut.');$data=$request->validate($this->rules());$d->update($data);if($d->responsable_traitement_id){$rule=$service->regle($this->module,$d->qualification_id,now());$d->delai_traitement_id=$rule?->id;$d->echeance_traitement=$service->calculer($this->module,$d->qualification_id,$d->date_reception,$d->date_affectation);$d->save();}return redirect()->route($this->prefix.'.show',$d->id)->with('success','Dossier mis à jour.');}
 public function destroy($id){$this->guardRoles('ADMIN','RQ');$d=$this->model()->findOrFail($id);$d->delete();return redirect()->route($this->prefix.'.index')->with('success','Dossier supprimé.');}
 public function affecter(Request $request,$id,EcheanceService $service){$this->guardRoles('ADMIN','RQ');$data=$request->validate(['responsable_traitement_id'=>'required|exists:users,id','motif'=>'nullable|string|max:3000']);$d=$this->model()->findOrFail($id);abort_if(in_array($d->statut,['cloture','annule']),422,'Ce dossier ne peut pas être affecté.');$old=$d->statut;$previous=$d->responsable_traitement_id;$now=now();$rule=$service->regle($this->module,$d->qualification_id,$now);DB::transaction(function()use($d,$data,$service,$rule,$previous,$now,$old){$d->responsable_traitement_id=$data['responsable_traitement_id'];$d->date_affectation=$now;$d->delai_traitement_id=$rule?->id;$d->echeance_traitement=$service->calculer($this->module,$d->qualification_id,$d->date_reception,$now);$d->statut='affecte';$d->save();$fk=$this->module==='reclamation'?'reclamation_id':'demande_assistance_id';DB::table('affectations')->insert(['module'=>$this->module,$fk=>$d->id,'responsable_precedent_id'=>$previous,'responsable_nouveau_id'=>$data['responsable_traitement_id'],'affecte_par'=>auth()->id(),'date_affectation'=>$now,'motif'=>$data['motif']??null,'created_at'=>$now]);$this->history($d,$old,'affecte','Affectation du dossier');});return back()->with('success',$d->echeance_traitement?'Dossier affecté. Échéance : '.$d->echeance_traitement->format('d/m/Y H:i'):'Dossier affecté. Aucun délai actif applicable : vérifiez le paramétrage.');}
 public function statut(Request $request,$id){$data=$request->validate(['statut'=>'required|in:en_cours,en_attente_information,traite,cloture,annule','causes_probleme'=>'nullable|string','action_entreprise'=>'nullable|string','commentaire'=>'nullable|string|max:3000','motif_annulation'=>'nullable|string']);$d=$this->model()->findOrFail($id);$old=$d->statut;$d->statut=$data['statut'];if(isset($data['causes_probleme']))$d->causes_probleme=$data['causes_probleme'];if(isset($data['action_entreprise']))$d->action_entreprise=$data['action_entreprise'];if($data['statut']==='traite'||$data['statut']==='cloture')$d->date_traitement=now();if($data['statut']==='cloture'){$d->date_cloture=now();$d->cloture_par=auth()->id();}if($data['statut']==='annule')$d->motif_annulation=$data['motif_annulation']??null;$d->save();$this->history($d,$old,$d->statut,$data['commentaire']??null);return back()->with('success','Statut mis à jour.');}
 public function relancer(Request $request,$id){$data=$request->validate(['motif'=>'required|string|max:3000','resultat'=>'nullable|string|max:3000','canal'=>'required|in:interne,telephone,email,courrier,autre','prochaine_action'=>'nullable|date']);$d=$this->model()->findOrFail($id);abort_if(in_array($d->statut,['traite','cloture','annule']),422,'Un dossier terminé ne peut pas faire l’objet d’une relance de traitement.');$fk=$this->module==='reclamation'?'reclamation_id':'demande_assistance_id';Relance::create(array_merge($data,['module'=>$this->module,$fk=>$d->id,'date_relance'=>now(),'responsable_relance_id'=>auth()->id(),'cree_par'=>auth()->id(),'statut'=>'effectuee']));return back()->with('success','Relance enregistrée.');}
 protected function history($d,$old,$new,$comment){$fk=$this->module==='reclamation'?'reclamation_id':'demande_assistance_id';DB::table('historique_statuts')->insert(['module'=>$this->module,$fk=>$d->id,'ancien_statut'=>$old,'nouveau_statut'=>$new,'commentaire'=>$comment,'modifie_par'=>auth()->id(),'date_changement'=>now(),'created_at'=>now()]);DB::table('journal_activites')->insert(['user_id'=>auth()->id(),'module'=>$this->module,'dossier_id'=>$d->id,'action'=>'statut_'.$new,'description'=>$comment,'adresse_ip'=>request()->ip(),'user_agent'=>substr((string)request()->userAgent(),0,500),'donnees_apres'=>json_encode(['statut'=>$new]),'created_at'=>now()]);}
}
